@page "/settings"
@rendermode InteractiveServer
@inject CascadingValueSource<ThemeInfo> ThemeSource

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-3" style="max-width: 480px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="mb-3">
            <label class="form-label">Color scheme</label>
            <select class="form-select" value="@selectedTheme" @onchange="OnThemeChanged">
                @foreach (var t in Enum.GetValues<Theme>())
                {
                    <option value="@t">@t</option>
                }
            </select>
        </div>

        <div class="mb-3">
            <label class="form-label">Accent color</label>
            <input type="color" class="form-control form-control-color"
                   value="@accentColor" @onchange="OnAccentChanged" />
        </div>

        <button class="btn btn-primary" @onclick="Save">Save preferences</button>

        @if (saved)
        {
            <span class="text-success ms-2">✓ Saved</span>
        }
    </div>
</div>

<div class="mt-3">
    <strong>Preview:</strong>
    <span class="badge" style="background-color: @accentColor;">
        @selectedTheme mode
    </span>
</div>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private Theme selectedTheme;
    private string accentColor = "#0d6efd";
    private bool saved;

    protected override void OnParametersSet()
    {
        if (Theme is not null)
        {
            selectedTheme = Theme.Theme;
            accentColor = Theme.AccentColor;
        }
    }

    private void OnThemeChanged(ChangeEventArgs e)
    {
        if (Enum.TryParse<Theme>(e.Value?.ToString(), out var t))
            selectedTheme = t;
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        accentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    private async Task Save()
    {
        await ThemeSource.NotifyChangedAsync(new ThemeInfo(selectedTheme, accentColor));
        saved = true;
    }
}

